function solid(x,y,ignore=null){return x<1.7||y<1.7||x>16||y>16||obs.some(o=>Math.hypot(x-o.x,y-o.y)<o.r+.24)||(!exitOpen()&&Math.abs(y-EXIT.y)<.28&&Math.abs(x-EXIT.x)<.85)||enemies.some(e=>e!==ignore&&e.hp>0&&Math.hypot(x-e.x,y-e.y)<.42)}
