function damage(v){if(view!=='game'||dash)return false;pl.lamp=Math.max(0,pl.lamp-v);if(pl.action!=='execution')heroTransient={id:'hit',start:clock,duration:.65};if(pl.lamp<=0){if(execution){let e=enemies.find(e=>e.id===execution.target);if(e&&e.hp>0){e.state='stagger';e.timer=0;}}execution=null;queued=null;pl.action=null;death=true;view='death';selected=0;keys.clear();goal=null;}save();return true;}
